insert into public.dg_product_evidence (user_id, product_id, source_type, source_id, source_url, source_label, title, raw_excerpt, observed_price, observed_currency, observed_attributes, metadata, confidence, reconciliation_status, historical) select 'c8b05141-4253-4bb0-9ca7-8ea32658a02e'::uuid, p.id, 'instagram_post', sid.value, urls.value, 'DailyGear Instagram @daily_gearz', p.name, left(p.description, 600), case when jsonb_array_length(p.attributes->'observed_prices_kes') = 1 then (p.attributes->'observed_prices_kes'->>0)::numeric else null end, 'KES', jsonb_build_object('source_ids', p.attributes->'source_ids', 'observed_prices_kes', p.attributes->'observed_prices_kes'), jsonb_build_object('source_account', p.attributes->>'source_account', 'source_image_urls', p.attributes->'source_image_urls'), case when p.attributes->>'confidence' = 'high' then 'high' when p.attributes->>'confidence' = 'medium' then 'medium' else 'low' end, 'candidate', true from public.dg_products p cross join lateral jsonb_array_elements_text(p.attributes->'source_ids') with ordinality sid(value, ord) join lateral jsonb_array_elements_text(p.attributes->'source_urls') with ordinality urls(value, ord) on urls.ord = sid.ord where p.user_id = 'c8b05141-4253-4bb0-9ca7-8ea32658a02e'::uuid and p.attributes->>'import_source' = 'instagram' and p.deleted_at is null and not exists (select 1 from public.dg_product_evidence e where e.product_id = p.id and e.source_id = sid.value) on conflict (user_id, source_type, source_id) do nothing;
